/* Portable study backups. Files are read locally; no upload endpoint. */
(()=>{'use strict';
const SIDE_KEYS=['fc_academy_v1','fc_teachers_v1','fc_offdays_v1','fc_preview_v1','fc_school_class','fc_places_v1','fc_avatar_v1','fc_planner_v1','fc_notes_v1','fc_cheer_v1','fc_mom_v1','fc_kid_v1','fc_life_v1'],APP='future-compass-study',VERSION=1,MAX_BYTES=4*1024*1024,EXTRA='compass-study-plus-v1',UNDO='compass-study-restore-undo-v1';
const isObj=x=>x!==null&&typeof x==='object'&&!Array.isArray(x),str=(x,n)=>typeof x==='string'&&x.length<=n;
function requireValue(ok){if(!ok)throw Error('invalid')}
function inspectBackup(raw){requireValue(str(raw,MAX_BYTES));const v=JSON.parse(raw);requireValue(isObj(v)&&v.app===APP&&v.version===VERSION&&isObj(v.core)&&isObj(v.extra));requireValue(typeof v.createdAt==='string'&&Number.isFinite(Date.parse(v.createdAt)));const c=v.core,p=v.extra;requireValue(Array.isArray(c.table)&&c.table.length===5&&c.table.every(d=>Array.isArray(d)&&d.length===7&&d.every(s=>str(s,40))));requireValue(Array.isArray(c.bags)&&c.bags.length===5&&c.bags.every(s=>str(s,200)));for(const k of ['tasks','dates','reviews']){requireValue(Array.isArray(c[k])&&c[k].length<=200);const ids=new Set();for(const x of c[k]){requireValue(isObj(x)&&str(x.id,80)&&x.id.length>0&&!ids.has(x.id)&&str(x.title,120)&&valid(x.date)&&typeof x.done==='boolean');ids.add(x.id);for(const [key,n]of [['subject',40],['note',800]])if(x[key]!==undefined)requireValue(str(x[key],n))}}
requireValue(isObj(c.timer)&&Number.isInteger(c.timer.duration)&&c.timer.duration>=60&&c.timer.duration<=7200&&Number.isFinite(c.timer.remaining)&&c.timer.remaining>=0&&c.timer.remaining<=c.timer.duration);requireValue(isObj(c.sessions)&&Object.keys(c.sessions).length<=5000);for(const [d,n]of Object.entries(c.sessions))requireValue(valid(d)&&Number.isInteger(n)&&n>=0&&n<=100);
requireValue([10,40,80].includes(p.mode)&&str(p.goal,120)&&str(p.subject,40));for(const [key,limit]of [['courses',60],['exams',200],['reviews',200]]){requireValue(isObj(p[key])&&Object.keys(p[key]).length<=limit);for(const [id,x]of Object.entries(p[key])){requireValue(id.length<=100&&!['__proto__','constructor','prototype'].includes(id)&&isObj(x));if(key==='courses'){requireValue(str(x.book,80)&&str(x.unit,100)&&str(x.pages,40))}if(key==='exams'){requireValue(str(x.rubric,800)&&Array.isArray(x.steps)&&x.steps.length<=30&&x.steps.every(s=>isObj(s)&&str(s.title,120)&&typeof s.done==='boolean'))}if(key==='reviews'){requireValue(valid(x.due)&&str(x.source,120)&&str(x.cause,40)&&Number.isInteger(x.stage)&&x.stage>=0&&x.stage<=3&&Array.isArray(x.attempts)&&x.attempts.length<=30&&x.attempts.every(a=>isObj(a)&&valid(a.date)&&['alone','hint','hard'].includes(a.result)))}}}
requireValue(Array.isArray(p.questions)&&p.questions.length<=100&&p.questions.every(x=>isObj(x)&&str(x.id,80)&&valid(x.date)&&str(x.title,200)&&str(x.answer,800)&&typeof x.done==='boolean'));requireValue(Array.isArray(p.logs)&&p.logs.length<=200&&p.logs.every(x=>isObj(x)&&valid(x.date)&&str(x.goal,120)&&str(x.explanation,400)&&['쉬움','적당함','버거움'].includes(x.feeling)));const core=restore(JSON.stringify(c));core.timer.end=0;core.timer.remaining=Math.ceil(core.timer.remaining);return {app:APP,version:VERSION,createdAt:v.createdAt,core,extra:window.studyPlusBridge.restore(JSON.stringify(p))}}
function snapshot(){tick();const c=JSON.parse(JSON.stringify(state));c.timer.end=0;const side={};for(const k of SIDE_KEYS){try{const v=localStorage.getItem(k);if(v!==null&&v.length<200000)side[k]=v}catch{}}return {app:APP,version:VERSION,createdAt:new Date().toISOString(),core:c,extra:window.studyPlusBridge.snapshot(),side}}
function atomicWrite(core,extra){const oldCore=localStorage.getItem(KEY),oldExtra=localStorage.getItem(EXTRA);try{localStorage.setItem(KEY,JSON.stringify(core));localStorage.setItem(EXTRA,JSON.stringify(extra))}catch(error){try{oldCore===null?localStorage.removeItem(KEY):localStorage.setItem(KEY,oldCore);oldExtra===null?localStorage.removeItem(EXTRA):localStorage.setItem(EXTRA,oldExtra)}catch{}throw error}}
function applyBackup(b,keepUndo=true){const previous=snapshot();if(keepUndo)localStorage.setItem(UNDO,JSON.stringify(previous));atomicWrite(b.core,b.extra);if(isObj(b.side))for(const k of SIDE_KEYS){const v=b.side[k];if(typeof v==='string'&&v.length<200000){try{JSON.parse(v);localStorage.setItem(k,v)}catch{}}}state=b.core;window.studyPlusBridge.replace(b.extra);render()}
window.studyBackupBridge={snapshot,inspect:inspectBackup,apply:applyBackup};
function exportBackup(){try{const raw=JSON.stringify(snapshot(),null,2),blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='study-backup-'+today()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notice('백업 파일 저장을 요청했어. 다운로드·파일 앱에서 확인해줘.')}catch{notice('백업을 만들지 못했어. 다시 시도해줘.')}}
const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;input.id='study-backup-file';document.body.append(input);
const dialog=document.createElement('dialog');dialog.className='study-dialog';dialog.setAttribute('aria-label','학습 기록 저장과 복원');document.body.append(dialog);let candidate=null,lastFocus;
function open(html){lastFocus=document.activeElement;dialog.innerHTML='<button class="dialog-close" aria-label="저장 창 닫기">×</button>'+html;dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close()}
dialog.addEventListener('close',()=>lastFocus?.focus());
function summary(b){return `시간표 ${b.core.table.flat().filter(Boolean).length}교시 · 할 일 ${b.core.tasks.length}개 · 시험·과제 ${b.core.dates.length}개 · 복습 ${b.core.reviews.length}개 · 질문 ${b.extra.questions.length}개`}
document.querySelector('#study-backup').onclick=exportBackup;document.querySelector('#study-restore').onclick=()=>{input.value='';input.click()};
input.onchange=async()=>{const file=input.files[0];if(!file)return;candidate=null;if(file.size>MAX_BYTES){notice('파일이 너무 커. 4MB 이하의 공부방 백업을 골라줘.');return}try{candidate=inspectBackup(await file.text());open(`<h2>📂 저장한 공부 기록 불러오기</h2><p>${esc(summary(candidate))}</p><p class="muted">백업 시각: ${esc(new Date(candidate.createdAt).toLocaleString('ko-KR'))}</p><p>현재 공부방 기록을 이 파일의 기록으로 바꿔요. 바꾸기 전 기록은 기기에 보관하며, 저장 도움말에서 복원 취소할 수 있어요.</p><p class="muted">타이머는 멈춘 상태로 가져와요. 파일은 서버로 전송하지 않아요.</p><button id="confirm-study-restore" class="primary">이 기록으로 복원</button>`);dialog.querySelector('#confirm-study-restore').onclick=()=>{try{applyBackup(candidate);dialog.close();notice('기록을 불러왔어. 저장 도움말에서 복원 취소할 수 있어.')}catch{notice('저장 공간이 부족하거나 저장이 차단되어 복원하지 못했어.')}}}catch{notice('공부방 백업 형식이 아니거나 파일이 손상됐어. 원래 기록은 그대로야.')}};
document.querySelector('#study-more').onclick=()=>{let hasUndo=false;try{hasUndo=!!localStorage.getItem(UNDO)}catch{}open(`<h2>💾 기록을 내 기기에 보관하기</h2><p>평소에는 이 브라우저에 자동 저장돼요. <b>백업 저장</b>은 시간표·과제·복습·질문·단원·학습 기록을 JSON 파일로 내려받아요.</p><ol><li>지금 기기에서 백업 저장을 눌러요.</li><li>파일을 다른 기기로 옮겨요.</li><li>다른 기기의 공부방에서 불러오기를 눌러요.</li></ol><p class="muted">진로 탐색 답변은 이 학습 백업에 포함되지 않아요. 다운로드 위치는 기기 설정에 따라 달라요. 브라우저 데이터를 지우기 전에 파일로 보관해줘요.</p>${hasUndo?'<button id="undo-study-restore">↩ 직전 복원 취소</button>':''}<h3>📱 홈 화면에서 앱처럼 열기</h3><p>아이폰: Safari 공유 → 홈 화면에 추가<br>안드로이드: 브라우저 메뉴 → 앱 설치 또는 홈 화면에 추가</p><a href="/#shiro-install">앱 설치 안내 열기 →</a>`);if(hasUndo)dialog.querySelector('#undo-study-restore').onclick=()=>{try{const previous=inspectBackup(localStorage.getItem(UNDO));applyBackup(previous,false);localStorage.removeItem(UNDO);dialog.close();notice('복원하기 전 공부 기록으로 돌아왔어.')}catch{notice('직전 기록을 되돌리지 못했어. 백업 파일을 확인해줘.')}}};
})();
